(* [comment removed for export] *)
Local Ltac transport_chunks_extra m a bs n Hn Ha Hl ::=
  repeat match goal with
  | H : accok ?lv ?frs m ?A ?N |- _ =>
      first [ apply (accok_write_out lv frs m a bs A N n Hn Ha Hl) in H; [ | tlia | tlia ]
            | apply (accok_write_gen lv frs m a bs A N n Hn Ha Hl) in H;
              [ | tlia
                | (* [comment removed for export] *)
                  first [ match goal with FS : sf_hide (A + 16 <= _ \/ _ <= A)%Z |- _ =>
                            solve [clear - FS; unfold sf_hide in FS; unfold shad, SHB in *; Z.div_mod_to_equations; lia] end
                        | match goal with FS : (A + 16 <= _ \/ _ <= A)%Z |- _ =>
                            solve [clear - FS; unfold shad, SHB in *; Z.div_mod_to_equations; lia] end ] ]
            | idtac "note: dropping accok fact (store may alias its shadow):" H; clear H ]
  end;
  lept_transport_extra m a bs n Hn Ha Hl;
  repeat match goal with
  | H : LIBH m |- _ =>
      first [ apply (LIBH_write m a bs n Hn Ha Hl) in H; [ | tlia ]
            | idtac "note: dropping LIBH (store may hit the library statics)"; clear H ]
  | H : io_ssp m |- _ =>
      first [ apply (io_ssp_write m a bs n Hn Ha Hl) in H; [ | unfold SEGTOP_A; tlia ]
            | idtac "note: dropping io_ssp"; clear H ]
  end.
(* [comment removed for export] *)
Ltac own_shadow_client a Hx :=
  lazymatch goal with OW : own_frame _ _ a _ |- _ =>
    let ff := fresh "ff" in let kk := fresh "kk" in let HFin := fresh "HFin" in let HF1 := fresh "HFa" in let HF2 := fresh "HFb" in
    destruct OW as (ff & kk & HFin & HF1 & HF2 & _);
    right; right; right; right; exists ff, kk; split;
    [ repeat match goal with E : rt_frames _ _ = _ |- _ => rewrite E end;
      first [exact HFin | right; exact HFin | right; right; exact HFin]
    | clear - Hx HF1 HF2; unfold shad, SHB in *; Z.div_mod_to_equations; lia ] end.
Local Ltac rt_transport_extra m m' AG ::=
  lept_rt_transport_extra m m' AG;   (* [comment removed for export] *)
  lazymatch type of AG with
  | agree_on (fun x => aclient _ _ _ x /\ ~ (_ <= x < _)%Z) _ _ =>
    repeat match goal with
    | H : accok ?lv ?frs m ?a ?n |- _ =>
        lazymatch type of AG with agree_on ?P2 _ _ =>
        let K := fresh "K" in
        first [ assert (K : accok lv frs m' a n);
                [ apply (accok_keep_P lv frs m m' P2 a n H AG);
                  [ clear; lia
                  | let x := fresh "x" in let Hx := fresh "Hx" in intros x Hx; split;
                    [ own_shadow_client a Hx
                    | first [ match goal with FP : (a + 16 <= ?f \/ ?f + 8192 <= a)%Z |- _ =>
                                solve [clear - Hx FP; unfold shad, SHB in *; Z.div_mod_to_equations; lia] end
                            | match goal with FP : sf_hide (a + 16 <= ?f \/ ?f + 8192 <= a)%Z |- _ =>
                                solve [clear - Hx FP; unfold sf_hide in FP; unfold shad, SHB in *; Z.div_mod_to_equations; lia] end ] ] ]
                | clear H; rename K into H ]
              | idtac "note: dropping accok fact (ex call):" H; clear H ]
        end
    end
  | _ => idtac
  end.
(* [comment removed for export] *)
Local Ltac accok_fp_on ::= idtac.
(* [comment removed for export] *)
Local Ltac fframe_tac ::=
  match goal with
  | FRSx : rt_frames _ _ = (?f, ?k) :: _, Hx : (?lo <= ?x < ?hi)%Z |- aclient _ _ _ ?x =>
      let v := eval vm_compute in (fs_size k) in
      lazymatch lo with
      | context [(_ / 8)%Z] =>
          right; right; right; right; exists f, k; split;
          [ solve [frames_in_tac] | change (fs_size k) with v; clear - Hx; unfold shad, SHB in *; Z.div_mod_to_equations; lia ]
      | _ =>
          right; right; right; left; exists f, k; split; [ solve [frames_in_tac] | change (fs_size k) with v; clear - Hx; lia ]
      end
  end.

Section CSELS_FRONT.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis SM7 : stack_malloc_7_contractF RT.
Hypothesis SF7 : stack_free_7_contractF RT.

(* [comment removed for export] *)
Ltac ivls5 LOR W1C W2C :=
  cbn [ivls_client]; split;
  [ intros zz Hzz; left; lazymatch goal with T : (_ + 16 <= 140737488355328)%Z |- _ => clear - Hzz T LOR end; ul
  | split; [intros zz Hzz; right; right; right; left; apply (W1C _ zz); [solve [frames_sub_tac]| clear - Hzz; lia]
  | split; [intros zz Hzz; right; right; right; left; apply (W2C _ zz); [solve [frames_sub_tac]| clear - Hzz; lia]
  | split; [intros zz Hzz; fframe_tac| split; [intros zz Hzz; fframe_tac| exact I]]]]].
Ltac pf5 PFS NFA LOR Hx :=
  let Q1 := fresh "Q" in
  cbn [outside]; destruct Hx as [Hx1 Hx2]; pose proof (PFS _ (conj Hx1 Hx2)) as Q1; destruct (NFA _ (conj Hx1 Hx2)) as [N1 N2];
  cbn [outside] in Hx2; unfold shad, SHB in N1, N2; clear - Q1 Hx2 N1 N2 LOR; repeat split; try exact I; first [lia | Z.div_mod_to_equations; lia].
(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac ss_call2 AF PFS NFA LOR W1C W2C usp SSL SA SB :=
  let W := fresh "WSA" in pose proof (proj2 SA) as W; cbn [cells_size csize Nat.add length Z.of_nat Pos.of_succ_nat Pos.succ] in W;
  once (at_call RT AF ltac:(ivls5 LOR W1C W2C) ltac:(fun Hx => pf5 PFS NFA LOR Hx));
  once (eapply cps_seq;
  [ let SS := fresh "SS" in pose proof SSL as SS; unfold set_shadow_contractF in SS;
    eapply SS with (n := 128); rt_side idtac;
    first [ exact W | solve [apply (wr_at_sub _ _ _ _ _ W); lia] | lazymatch goal with |- ?g => idtac "ss_call LEFT:" g end ]
  | ]);
  once (after_call RT AF);
  once (fold_ag ltac:(fun Hx => let N1 := fresh "N" in let N2 := fresh "N" in pose proof (NFA _ Hx) as [N1 N2]; unfold shad, SHB in N1, N2; split;
                [ apply (aclient_mono _ _ usp _ _ _ _ (proj1 Hx)); [solve [live_sub_tac]| solve [frames_sub_tac]| lia]
                | clear - N1 N2; Z.div_mod_to_equations; lia ]));
  once (lazymatch goal with B : bytes_at asegs ?m2 ?d (repeat ?b (Z.to_nat 128)) |- _ =>
    assert (SB : rw_cells asegs m2 d [CB 128%nat (repeat b 128%nat)])
      by (change (Z.to_nat 128) with 128%nat in B; split;
          [ split; [cbn; split; [reflexivity| exact I]| cbn [cells_bytes cbytes]; rewrite app_nil_r; exact B]
          | cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ];
            first [exact W | apply (wr_at_sub _ _ _ _ _ W); lia] ]);
    clear B
  end);
  clear W; try clear SA;
  once (refresh RT AF); unfold shad, SHB in *; unfold STACK_WIN, USTACK_TOP, RT_STACK, SEGTOP_A in *;
  repeat match goal with H : rt_sp0 RT _ = _ |- _ => rewrite H in * end.
Ltac hsum mm := repeat match goal with H : ?T |- _ => lazymatch T with context [mm] => first [ lazymatch T with rw_cells _ _ ?A _ => idtac H ": cells at" A | accok _ _ _ ?a _ => idtac H ": accok" a | acc _ _ ?a ?n => idtac H ": acc" a n | wr_at _ _ ?a ?n => idtac H ": wr_at" a n end | idtac H ]; fail end end.
Ltac hs := lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) => idtac "cur mem" mm; hsum mm | |- cps _ (ASTA _ _ _ (eq (MS _ _ _ _ _ ?mm _))) _ =>  idtac "cur mem" mm; hsum mm end.
Ltac show_pc := lazymatch goal with
  | |- cps _ (ASTA _ _ _ (eq (MS _ _ ?pc _ _ _ _))) _ => idtac "CPS-MS pc=" pc
  | |- cps _ (ASTA _ _ _ (eq ?st)) _ => idtac "CPS other"
  | |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "EVT pc=" pc
  | |- ?g => idtac "OTHER" end.

(* [comment removed for export] *)
Ltac brS SHAPE := lazymatch goal with
  | |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
      first [ replace c with true by (clear - SHAPE; destruct SHAPE as [(-> & ->)|(-> & ->)]; vm_compute; reflexivity); cbv iota
            | replace c with false by (clear - SHAPE; destruct SHAPE as [(-> & ->)|(-> & ->)]; vm_compute; reflexivity); cbv iota ]
  | |- _ => idtac end.

Theorem csels_front_16 :
  (forall (Σ : rts RT) PMc (ra gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (usp lo : Z) (m : mem)
          (size dir p1 p2 : Z) (ras : list Z),
     csels_ctx RT Σ PMc ra usp lo m size dir p1 p2 ras ->
     csels_cut1_16 RT Σ PMc ra gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F usp lo m size dir p1 p2
                  (csels_Q RT Σ PMc ra gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F usp lo m size p1 p2)) ->
  selectComposableSels_al RT 16.
Proof using AF GP FKC SM7.
ltac2:(KReplay.run1 (kr_t_Po_csels_front16 ()) ["CSELS_FRONT"] (String.concat "" [kr_b_Po_csels_front16_1_1 (); kr_b_Po_csels_front16_1_2 ()])). Qed.
End CSELS_FRONT.
